WITH exploded AS (SELECT id, customer_id, coupon_codes, INLINE(items) FROM carts) SELECT *, ROUND(price / SUM(price) OVER (PARTITION BY customer_id), 4) AS price_share, RANK() OVER (ORDER BY qty DESC NULLS FIRST) AS qty_rank, MAX(qty) OVER (PARTITION BY customer_id, promo) AS customer_id_max_qty, MIN(qty) OVER w_hist AS promo_min_qty FROM exploded WINDOW w_hist AS (PARTITION BY promo);
